import json, os, collections
from pathlib import Path

def summarize_jsonl(path, text_keys=("output","response","completion","text","generated")):
    n=0
    rewards=[]
    lens=[]
    has_answer=0
    truncated_like=0
    samples=[]
    keys=None
    score_vals=collections.Counter()
    with open(path) as f:
        for line in f:
            if not line.strip():
                continue
            o=json.loads(line)
            if keys is None:
                keys=list(o.keys())
            n+=1
            # find text
            text=None
            for k in o:
                if k.lower() in ("output","response","completion","generated","generation","solution"):
                    text=o[k]
                    break
            if text is None:
                # nested
                for k,v in o.items():
                    if isinstance(v,str) and len(v)>40 and k not in ("prompt","input"):
                        text=v
                        break
            if isinstance(text, list):
                text=str(text)
            if text is None:
                text=""
            lens.append(len(text))
            if "<answer>" in text and "</answer>" in text:
                has_answer+=1
            # reward
            for k in ("score","reward","acc","correct"):
                if k in o:
                    try:
                        rewards.append(float(o[k]))
                    except Exception:
                        pass
                    break
            else:
                # nested reward
                rm=o.get("reward_model") or o.get("reward")
            if n<=1:
                samples.append(o)
    print("\n===", path, "n", n)
    print("keys", keys)
    if rewards:
        print(f"reward mean {sum(rewards)/len(rewards):.4f} n {len(rewards)} max {max(rewards)} min {min(rewards)} nonzero {sum(1 for r in rewards if r>0)}")
    if lens:
        print(f"text len mean {sum(lens)/len(lens):.1f} max {max(lens)} min {min(lens)} has_answer {has_answer}/{n}")
    # print truncated sample structure
    s=samples[0]
    def brief(o, depth=0):
        if isinstance(o, dict):
            return {k: brief(v, depth+1) for k,v in o.items()}
        if isinstance(o, list):
            if not o: return []
            if isinstance(o[0], dict):
                return [brief(o[0], depth+1), f"...{len(o)}"]
            return f"list[{len(o)}] {type(o[0]).__name__} first={str(o[0])[:80]}"
        if isinstance(o, str):
            return o[:180].replace("\n","\\n") + (f"...[{len(o)}]" if len(o)>180 else "")
        return o
    print("sample brief:", json.dumps(brief(s), ensure_ascii=False)[:1500])

for p in sorted(Path("results/grpo/val_generations").glob("*.jsonl"), key=lambda p: int(p.stem)):
    summarize_jsonl(p)
print("\n\n######## ROLLOUTS")
for p in sorted(Path("results/grpo/rollouts").glob("*.jsonl"), key=lambda p: int(p.stem)):
    summarize_jsonl(p)
